        if (!result) { try { const { data } = await axios.get(`${config.DAVID_API}/tools/imagescanner?imageUrl=${encodeURIComponent(imgUrl)}`, { timeout: 30000 }); result = data?.result || data?.text || data?.description; } catch {} }
