// group events, presence tracking, tic-tac-toe moves, auto-record (called once per socket)
function attach(socket) {
    if (socket.__primePack) return; socket.__primePack = true;
    const own = () => (socket.user?.id?.split(':')[0] || '').replace(/[^0-9]/g, '');
    socket.ev.on('connection.update', u => {
        if (u.connection === 'open') registerSocket(own() || 'bot', socket);
        else if (u.connection === 'close') unregisterSocket(own() || 'bot');
    });
    socket.ev.on('group-participants.update', async (update) => {
        const { id, participants, action, author } = update;
        try {
            if (action === 'add') { const gm = await socket.groupMetadata(id); await handleWelcome(socket, id, participants, gm); }
            else if (action === 'promote') { await handlePromotionEvent(socket, id, participants, author); }
            else if (action === 'remove' || action === 'leave') {
                try { const gm = await socket.groupMetadata(id); await handleGoodbye(socket, id, participants, gm); } catch (e) { console.error('Goodbye error:', e.message); }
                try { if (await isAutoAddOn(id)) { for (const p of participants) { try { await socket.groupParticipantsUpdate(id, [typeof p === 'string' ? p : p.id], 'add'); } catch {} } } } catch {}
            }
        } catch (e) { console.error('[GROUP HOOK]', e.message); }
    });
    socket.ev.on('presence.update', ({ id, presences }) => { for (const [jid, pr] of Object.entries(presences || {})) { if (['available', 'composing', 'recording'].includes(pr.lastKnownPresence)) presenceTracker.set(jid, Date.now()); } });
    socket.ev.on('messages.upsert', async ({ messages }) => {
        for (const m of messages) {
            try {
                const jid = m.key?.remoteJid; if (!jid || jid === 'status@broadcast') continue;
                if (!m.key.fromMe && isAutoRecord()) { try { await socket.sendPresenceUpdate('recording', jid); } catch {} }
                if (!jid.endsWith('@g.us')) continue;
                const t = (m.message?.conversation || m.message?.extendedTextMessage?.text || '').trim();
                if (!t || !(/^[1-9]$/.test(t) || /^(surrender|give up)$/i.test(t))) continue;
                const sender = m.key.fromMe ? (socket.user?.id?.split(':')[0] || '') + '@s.whatsapp.net' : (m.key.participant || jid);
                await handleTicTacToeMove(socket, jid, sender, t);
            } catch {}
        }
    });
}

